package logging

import (
    "net/http"
    "github.com/google/uuid"
    "go.uber.org/zap"
)

func CorrelationLoggingMiddleware(logger *zap.Logger, next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        corrID := r.Header.Get("X-Correlation-ID")
        if corrID == "" {
            corrID = uuid.NewString()
        }
        w.Header().Set("X-Correlation-ID", corrID)

        // Create request-scoped structured logger
        reqLogger := logger.With(
            zap.String("correlation_id", corrID),
            zap.String("method", r.Method),
            zap.String("path", r.URL.Path),
        )

        reqLogger.Info("Incoming HTTP request started")
        next.ServeHTTP(w, r)
        reqLogger.Info("Incoming HTTP request completed")
    })
}
